var COM = {"0": "<p>Certo. Art. 125: reduzidas a zero as alíquotas.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "1": "<p>Errado. O Anexo I é exclusive hortícolas, frutas e ovos; esses constam do Anexo XV.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "2": "<p>Certo. Art. 126, § 1º.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "3": "<p>Errado. Art. 126, § 5º: documento emitido pelo adquirente e efetivo pagamento ao fornecedor.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "4": "<p>Certo. Art. 128, I, II e V (os medicamentos de alíquota zero têm tratamento próprio).</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "5": "<p>Errado. Art. 129, parágrafo único, II: não se aplica a outras operações ocorridas no âmbito das escolas.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "6": "<p>Certo. Art. 130, parágrafo único.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "7": "<p>Certo. Item 30 do Anexo III.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "8": "<p>Certo. Item 6 do Anexo II.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "9": "<p>Certo. Art. 131, § 1º.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "10": "<p>Errado. Art. 131, § 2º: tão somente inclusão de dispositivos inexistentes que atendam às mesmas finalidades.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "11": "<p>Certo. Art. 133, caput.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "12": "<p>Errado. Art. 132, § 1º: requisitos da norma do órgão público competente.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "13": "<p>Certo. Texto expresso.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "14": "<p>Certo. Item 10 do Anexo VII.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "15": "<p>Errado. Redução de 60%, mas o art. 137 não remete a anexo; o conceito está no próprio artigo.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "16": "<p>Certo. Art. 137, § 1º, II.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "17": "<p>Certo. Art. 136.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "18": "<p>Errado. O Anexo VII tem redução de 60%; a cesta (zero) é o Anexo I.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "19": "<p>Certo. Art. 138, § 1º.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "20": "<p>Errado. O anexo traz serviços agronômicos, veterinários, pulverização, análises laboratoriais, entre outros.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "21": "<p>Certo. Item 12 do Anexo IX.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "22": "<p>Errado. Art. 138, § 3º: só a parcela usada na produção de bem vendido a adquirentes com direito aos créditos presumidos do art. 168.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "23": "<p>Certo. Gestão e exploração do desporto inclui cessão de direitos e transferência de atletas.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "24": "<p>Errado. Art. 140, caput e parágrafo único: só ente público (direta, autarquias e fundações); outros pagam alíquota-padrão.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "25": "<p>Certo. Art. 139, § 3º.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "26": "<p>Certo. Art. 142, II, com a redação da LC 227/2026.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>", "27": "<p>Certo. Art. 139, IV.</p><p class='fb-fonte'>LC 214/2025 — Anexos I a XI e arts. 125 a 142</p>"};
